.message-input textarea:focus {
    border-color: #4a6cf7;
}

.send-btn {
    align-self: flex-end;
    padding: 8px 20px;
    background: #4a6cf7;
    color: #fff;
    border: none;
    border-radius: 6px;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s;
}

.send-btn:hover:not(:disabled) {
    background: #3451c7;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: default;
}

