@using sv_0860cea5a4ce4063b948107d85eb7e9f.Services

<div class="channel-sidebar">
    <div class="sidebar-header">
        <h2>Channels</h2>
    </div>
    <ul class="channel-list">
        @foreach (var channel in Channels)
        {
            <li class="channel-item @(channel.Id == ActiveChannelId ? "active" : "")"
                @onclick="() => OnChannelSelected.InvokeAsync(channel.Id)">
                <div class="channel-name-row">
                    <span class="channel-name"># @channel.Name</span>
                    @if (channel.UnreadCount > 0)
                    {
                        <span class="unread-badge">@channel.UnreadCount</span>
                    }
                </div>
                @if (!string.IsNullOrWhiteSpace(channel.Description))
                {
                    <div class="channel-desc">@Truncate(channel.Description, 50)</div>
                }
            </li>
        }
    </ul>
</div>

@code {
    [Parameter, EditorRequired] public List<Channel> Channels { get; set; } = [];
    [Parameter] public int ActiveChannelId { get; set; }
    [Parameter] public EventCallback<int> OnChannelSelected { get; set; }

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : text[..maxLength] + "…";
}

.channel-sidebar {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #2b2d42;
    color: #ccc;
    overflow: hidden;
}

.sidebar-header {
    padding: 16px;
    border-bottom: 1px solid rgba(255,255,255,0.08);
}

.sidebar-header h2 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #fff;
}

.channel-list {
    list-style: none;
    margin: 0;
    padding: 8px 0;
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 8px 16px;
    cursor: pointer;
    border-left: 3px solid transparent;
    transition: background 0.1s;
}

.channel-item:hover {
    background: rgba(255,255,255,0.06);
}

.channel-item.active {
    background: rgba(255,255,255,0.1);
    border-left-color: #4a6cf7;
}

.channel-name-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.channel-name {
    font-weight: 600;
    font-size: 0.9rem;
    color: #e0e0e0;
}

.channel-item.active .channel-name {
    color: #fff;
}

.unread-badge {
    background: #e74c3c;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 1px 7px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

.channel-desc {
    font-size: 0.75rem;
    color: #999;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

@using sv_0860cea5a4ce4063b948107d85eb7e9f.Services

<div class="message-area">
    <div class="area-header">
        <h3># @Channel.Name</h3>
        <span class="header-desc">@Channel.Description</span>
    </div>

    <div class="message-list" @ref="_messageListRef">
        @if (_loadingMore)
        {
            <div class="loading-indicator">Loading older messages…</div>
        }
        else if (HasMore)
        {
            <button class="load-more-btn" @onclick="LoadOlder">↑ Load older messages</button>
        }

        @foreach (var msg in Messages)
        {
            <ChatMessage Message="msg"
                         IsThreadStarter="ThreadSummaries.ContainsKey(msg.Id)"
                         ReplyCount="ThreadSummaries.GetValueOrDefault(msg.Id)?.ReplyCount ?? 0"
                         ShowReplyAction="true"
                         OnOpenThread="() => OnOpenThread.InvokeAsync(msg.Id)"
                         OnReact="(emoji) => OnReact.InvokeAsync((msg.Id, emoji))" />
        }

        @if (Messages.Count == 0 && !_loadingMore)
        {
            <div class="empty-state">No messages yet. Start the conversation!</div>
        }
    </div>

    <MessageInput Placeholder="@($"Message #{Channel.Name}")"
                  ButtonLabel="Send"
                  OnSubmit="OnSendMessage" />
</div>

@code {
    [Parameter, EditorRequired] public Channel Channel { get; set; } = default!;
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, ThreadSummary> ThreadSummaries { get; set; } = [];
    [Parameter] public bool HasMore { get; set; }
    [Parameter] public EventCallback OnLoadOlder { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }

    private ElementReference _messageListRef;
    private bool _loadingMore;

    private async Task LoadOlder()
    {
        _loadingMore = true;
        await OnLoadOlder.InvokeAsync();
        _loadingMore = false;
    }
}

.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #fff;
    overflow: hidden;
}

.area-header {
    padding: 12px 20px;
    border-bottom: 1px solid #e0e0e0;
    background: #fafbfc;
    flex-shrink: 0;
}

.area-header h3 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #1a1a1a;
}

.header-desc {
    font-size: 0.8rem;
    color: #888;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
    display: flex;
    flex-direction: column;
}

.loading-indicator {
    text-align: center;
    padding: 12px;
    color: #888;
    font-size: 0.85rem;
}

.load-more-btn {
    display: block;
    margin: 8px auto;
    padding: 6px 16px;
    background: #eef1f8;
    border: 1px solid #d0d7e8;
    border-radius: 6px;
    color: #4a6cf7;
    font-size: 0.8rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s;
}

.load-more-btn:hover {
    background: #dde3f1;
}

.empty-state {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #aaa;
    font-size: 0.95rem;
}

@using sv_0860cea5a4ce4063b948107d85eb7e9f.Services

<div class="thread-panel">
    <div class="thread-header">
        <h4>Thread</h4>
        <button class="close-btn" @onclick="OnClose" title="Close thread">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="root-message-quote">
            <ChatMessage Message="RootMessage"
                         ShowReplyAction="false"
                         OnReact="(emoji) => OnReact.InvokeAsync((RootMessage.Id, emoji))" />
        </div>

        <div class="thread-divider">
            <span>@Replies.Count @(Replies.Count == 1 ? "reply" : "replies")</span>
        </div>

        <div class="thread-replies">
            @foreach (var reply in Replies)
            {
                <ChatMessage Message="reply"
                             ShowReplyAction="false"
                             OnReact="(emoji) => OnReact.InvokeAsync((reply.Id, emoji))" />
            }
        </div>

        <MessageInput Placeholder="Reply in thread…"
                      ButtonLabel="Reply"
                      OnSubmit="OnSendReply" />
    }
</div>

