.channel-sidebar {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #2b2d42;
    color: #ccc;
    overflow: hidden;
}

.sidebar-header {
    padding: 16px;
    border-bottom: 1px solid rgba(255,255,255,0.08);
}

.sidebar-header h2 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #fff;
}

