@using sv_0860cea5a4ce4063b948107d85eb7e9f.Services

<div class="channel-sidebar">
    <div class="sidebar-header">
        <h2>Channels</h2>
    </div>
    <ul class="channel-list">
        @foreach (var channel in Channels)
        {
            <li class="channel-item @(channel.Id == ActiveChannelId ? "active" : "")"
                @onclick="() => OnChannelSelected.InvokeAsync(channel.Id)">
                <div class="channel-name-row">
                    <span class="channel-name"># @channel.Name</span>
                    @if (channel.UnreadCount > 0)
                    {
                        <span class="unread-badge">@channel.UnreadCount</span>
                    }
                </div>
                @if (!string.IsNullOrWhiteSpace(channel.Description))
                {
                    <div class="channel-desc">@Truncate(channel.Description, 50)</div>
                }
            </li>
        }
    </ul>
</div>

@code {
    [Parameter, EditorRequired] public List<Channel> Channels { get; set; } = [];
    [Parameter] public int ActiveChannelId { get; set; }
    [Parameter] public EventCallback<int> OnChannelSelected { get; set; }

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : text[..maxLength] + "…";
}

@using sv_0860cea5a4ce4063b948107d85eb7e9f.Services

<div class="message-area">
    <div class="area-header">
        <h3># @Channel.Name</h3>
        <span class="header-desc">@Channel.Description</span>
    </div>

    <div class="message-list" @ref="_messageListRef">
        @if (_loadingMore)
        {
            <div class="loading-indicator">Loading older messages…</div>
        }
        else if (HasMore)
        {
            <button class="load-more-btn" @onclick="LoadOlder">↑ Load older messages</button>
        }

        @foreach (var msg in Messages)
        {
            <ChatMessage Message="msg"
                         IsThreadStarter="ThreadSummaries.ContainsKey(msg.Id)"
                         ReplyCount="ThreadSummaries.GetValueOrDefault(msg.Id)?.ReplyCount ?? 0"
                         ShowReplyAction="true"
                         OnOpenThread="() => OnOpenThread.InvokeAsync(msg.Id)"
                         OnReact="(emoji) => OnReact.InvokeAsync((msg.Id, emoji))" />
        }

        @if (Messages.Count == 0 && !_loadingMore)
        {
            <div class="empty-state">No messages yet. Start the conversation!</div>
        }
    </div>

    <MessageInput Placeholder="@($"Message #{Channel.Name}")"
                  ButtonLabel="Send"
                  OnSubmit="OnSendMessage" />
</div>

@code {
    [Parameter, EditorRequired] public Channel Channel { get; set; } = default!;
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, ThreadSummary> ThreadSummaries { get; set; } = [];
    [Parameter] public bool HasMore { get; set; }
    [Parameter] public EventCallback OnLoadOlder { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }

    private ElementReference _messageListRef;
    private bool _loadingMore;

    private async Task LoadOlder()
    {
        _loadingMore = true;
        await OnLoadOlder.InvokeAsync();
        _loadingMore = false;
    }
}

