arguments.file_text:
@page "/chat"
@layout Components.Layout.ChatLayout
@rendermode InteractiveServer
@using sv_0860cea5a4ce4063b948107d85eb7e9f.Services
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-container">
    <div class="sidebar-col">
        <ChannelSidebar Channels="_channels"
                        ActiveChannelId="_activeChannelId"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="main-col @(_threadOpen ? "" : "expanded")">
        @if (_activeChannel is not null)
        {
            <MessageArea Channel="_activeChannel"
                         Messages="_messages"
                         ThreadSummaries="_threadSummaries"
                         HasMore="_hasMore"
                         OnLoadOlder="LoadOlderMessages"
                         OnOpenThread="OpenThread"
                         OnReact="HandleReaction"
                         OnSendMessage="SendMessage" />
        }
        else
        {
            <div class="no-channel">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (_threadOpen)
    {
        <div class="thread-col">
            <ThreadPanel RootMessage="_threadRootMessage"
                         Replies="_threadReplies"
                         OnClose="CloseThread"
                         OnReact="HandleReaction"
                         OnSendReply="SendThreadReply" />
        </div>
    }
</div>

@code {
    private const int PageSize = 30;

    private List<Channel> _channels = [];
    private int _activeChannelId;
    private Channel? _activeChannel;
    private List<Message> _messages = [];
    private Dictionary<int, ThreadSummary> _threadSummaries = [];
    private bool _hasMore = true;

    // Thread state
    private bool _threadOpen;
    private Message? _threadRootMessage;
    private List<Message> _threadReplies = [];

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _activeChannelId = channelId;
        _activeChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _messages = [];
        _hasMore = true;
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];

        await LoadMessages();
        await ChatService.MarkChannelReadAsync(channelId);

        // Refresh channels to update unread counts
        _channels = await ChatService.GetChannelsAsync();
    }

    private async Task LoadMessages()
    {
        var batch = await ChatService.GetMessagesAsync(_activeChannelId, _messages.Count, PageSize);
        _hasMore = batch.Count == PageSize;
        _messages.InsertRange(0, batch);
        BuildThreadSummaries();
    }

    private async Task LoadOlderMessages() => await LoadMessages();

    private void BuildThreadSummaries()
    {
        _threadSummaries = [];
        // Group reply messages by their ReplyToId to produce thread summaries
        var replies = _messages.Where(m => m.ReplyToId is not null).ToList();
        foreach (var group in replies.GroupBy(m => m.ReplyToId!.Value))
        {
            _threadSummaries[group.Key] = new ThreadSummary(
                group.Key,
                group.Count(),
                group.Max(m => m.SentAt));
        }
    }

    private async Task OpenThread(int rootMessageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == rootMessageId);
        if (_threadRootMessage is null) return;

        _threadReplies = await ChatService.GetThreadAsync(rootMessageId);
        _threadOpen = true;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh messages to show updated reactions
        var freshMessages = await ChatService.GetMessagesAsync(_activeChannelId, 0, _messages.Count);
        _messages = freshMessages;

        // Refresh thread if open
        if (_threadOpen && _threadRootMessage is not null)
        {
            _threadReplies = await ChatService.GetThreadAsync(_threadRootMessage.Id);
            _threadRootMessage = _messages.FirstOrDefault(m => m.Id == _threadRootMessage.Id)
                                 ?? _threadRootMessage;
        }
    }

    private async Task SendMessage(string content)
    {
        var msg = await ChatService.SendMessageAsync(_activeChannelId, content, null);
        _messages.Add(msg);
    }

    private async Task SendThreadReply(string content)
    {
        if (_threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(_activeChannelId, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);
        _messages.Add(reply);
        BuildThreadSummaries();
    }
}

.chat-container {
    display: flex;
    height: 100vh;
    width: 100%;
    overflow: hidden;
}

.sidebar-col {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
}

.main-col {
    flex: 1;
    min-width: 0;
    transition: flex 0.2s ease;
}

.main-col.expanded {
    flex: 1;
}

.thread-col {
    width: 25%;
    min-width: 280px;
    max-width: 400px;
    flex-shrink: 0;
}

.no-channel {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: #aaa;
    font-size: 1.1rem;
}

